using System;using System.Security.Principal;
internal static class UsbExactBlockBaselineQualification{
 [STAThread]static int Main(){string stage="authorization";try{if(!new WindowsPrincipal(WindowsIdentity.GetCurrent()).IsInRole(WindowsBuiltInRole.Administrator))return 3;var empty=UsbExactBlockGpo.Empty();stage="authenticated_binding";using(var lease=new UsbExactBlockBaseline(key=>UsbExactBlockGpo.ValidateLegacyOverlay(key,empty,empty,false))){stage="lease_check";lease.Check();var provider=UsbExactBlockGpo.CreateReviewedMachine(lease,()=>{});stage="saved_effective_readback";provider.Verify(empty);stage="final_lease_check";lease.Check();Console.WriteLine("PASS authenticated existing legacy binding and actual saved/effective empty managed baseline; read-only, no policy/device changes");return 0;}}catch(Exception e){Console.WriteLine("FAIL readonly exact baseline stage="+stage);for(var cause=e;cause!=null;cause=cause.InnerException){Console.WriteLine("category="+cause.GetType().Name+" hresult="+cause.HResult.ToString("X8")+" method="+(cause.TargetSite==null?"unknown":cause.TargetSite.Name)+" context="+(cause is InvalidOperationException?cause.Message:"redacted"));}return 1;}}
}
